#!/usr/bin/python3 -I
"""sync_remote.py -- write satellite_remote.py's block into every tool of the toolkit.

    ./sync_remote.py           write it wherever it differs
    ./sync_remote.py --check   change nothing; exit 1 and name the files whose copy differs

Each tool holds the block between these two lines (the tool's own code is never touched):

    # >>> satellite_remote >>> (generated by sync_remote.py from satellite_remote.py -- edit that file, not this block)
    # <<< satellite_remote <<<

so every tool is still ONE file that can be copied anywhere and go remote by itself.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SOURCE = os.path.join(HERE, "satellite_remote.py")
BEGIN = "# >>> satellite_remote >>> (generated by sync_remote.py from satellite_remote.py -- edit that file, not this block)"
END = "# <<< satellite_remote <<<"
FROM, TO = "# ---- embed from here ----", "# ---- embed to here ----"
TOOLS = ("satellite_toolkit.py",
         "tools/clang/enterprise_clang_tool.py",
         "tools/gcc/enterprise_gcc_tool.py",
         "tools/python/enterprise_python_tool.py",
         "tools/pypy/enterprise_pypy_tool.py",
         "tools/kernel/enterprise_linux_kernel_tool.py",
         "tools/satellite/install_build_requirements.py")


def block():
    with open(SOURCE) as f:
        lines = f.read().split("\n")
    a, b = lines.index(FROM), lines.index(TO)
    return "\n".join(lines[a + 1:b])


def synced(text, body):
    """-> the file's text with the block replaced, or None when it has no markers."""
    lines = text.split("\n")
    starts = [i for i, l in enumerate(lines) if l.startswith("# >>> satellite_remote >>>")]
    ends = [i for i, l in enumerate(lines) if l == END]
    if len(starts) != 1 or len(ends) != 1 or ends[0] < starts[0]:
        return None
    return "\n".join(lines[:starts[0]] + [BEGIN, body] + lines[ends[0]:])


def main(argv):
    check = "--check" in argv
    body = block()
    bad, changed = [], []
    for rel in TOOLS:
        path = os.path.join(HERE, rel)
        if not os.path.exists(path):
            bad.append("%s: missing" % rel)
            continue
        with open(path) as f:
            text = f.read()
        new = synced(text, body)
        if new is None:
            bad.append("%s: no (or more than one) marker pair" % rel)
            continue
        if new != text:
            changed.append(rel)
            if not check:
                tmp = path + ".syncing"
                with open(tmp, "w") as f:
                    f.write(new)
                os.chmod(tmp, os.stat(path).st_mode)
                os.replace(tmp, path)
    for line in bad:
        print("  ! " + line)
    for rel in changed:
        print(("  differs: " if check else "  written: ") + rel)
    if not bad and not changed:
        print("  every tool holds the same satellite_remote block")
    return 1 if bad or (check and changed) else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
